              val wrapped: List<Any?> = try {
                listOf(api.connectMutual(hostArg, portArg, labelArg, peerSha256Arg))
              } catch (exception: Throwable) {
                TlsApiPigeonUtils.wrapError(exception)
              }
              reply.reply(wrapped)
            }
          }
        } else {
          channel.setMessageHandler(null)
        }
      }
    }
  }
}

private class TlsApiPigeonStreamHandler<T>(
    val wrapper: TlsApiPigeonEventChannelWrapper<T>
) : EventChannel.StreamHandler {
  var pigeonSink: PigeonEventSink<T>? = null

  override fun onListen(p0: Any?, sink: EventChannel.EventSink) {
    pigeonSink = PigeonEventSink<T>(sink)
    wrapper.onListen(p0, pigeonSink!!)
  }

  override fun onCancel(p0: Any?) {
    pigeonSink = null
    wrapper.onCancel(p0)
  }
}

interface TlsApiPigeonEventChannelWrapper<T> {
  open fun onListen(p0: Any?, sink: PigeonEventSink<T>) {}

  open fun onCancel(p0: Any?) {}
}

abstract class TlsEventsStreamHandler : TlsApiPigeonEventChannelWrapper<TlsEventMsg> {
  companion object {
    fun register(messenger: BinaryMessenger, streamHandler: TlsEventsStreamHandler, instanceName: String = "") {
      var channelName: String = "dev.flutter.pigeon.mediahro.TlsEventsApi.tlsEvents"
      if (instanceName.isNotEmpty()) {
        channelName += ".$instanceName"
      }
      val internalStreamHandler = TlsApiPigeonStreamHandler<TlsEventMsg>(streamHandler)
      EventChannel(messenger, channelName, TlsApiPigeonMethodCodec).setStreamHandler(internalStreamHandler)
    }
  }
// Implement methods from TlsApiPigeonEventChannelWrapper
override fun onListen(p0: Any?, sink: PigeonEventSink<TlsEventMsg>) {}

override fun onCancel(p0: Any?) {}
}
      
